"""
Autobahn Defender v2.0 -- Alert system for automated threat monitoring.

Stores security alerts generated by the AI threat monitor in a JSONL file.
Alerts have severity levels, recommended actions (copy-paste commands),
and lifecycle states (active -> dismissed/resolved).

File: ~/.local/share/autobahn-defender/intel/alerts.jsonl

Alert schema:
{
  "id": "auto-generated-uuid",
  "severity": "critical" | "high" | "medium",
  "title": "Zero-day in OpenSSL 3.0.13 (CVE-2025-XXXX)",
  "affected_package": "openssl",
  "installed_version": "3.0.13",
  "patch_available": true,
  "recommended_action": "sudo apt update && sudo apt upgrade openssl",
  "alternative_action": "sudo systemctl stop ...",  # if no patch
  "source": "Ubuntu Security Notice / The Hacker News / etc.",
  "cve_id": "CVE-2025-XXXX",       # optional
  "timestamp": "2025-08-10T12:00:00Z",
  "status": "active",               # active | dismissed | resolved
  "resolved_at": null,              # ISO timestamp when resolved
}
"""

from __future__ import annotations

import json
import os
import uuid
from datetime import datetime, timezone
from pathlib import Path
from typing import Any

from . import INTEL_DIR
from .intel_db import ensure_dirs

ALERTS_FILE = "alerts.jsonl"


def _path() -> Path:
    return INTEL_DIR / ALERTS_FILE


def create_alert(
    severity: str,
    title: str,
    recommended_action: str,
    affected_package: str = "",
    installed_version: str = "",
    patch_available: bool = False,
    alternative_action: str = "",
    source: str = "",
    cve_id: str = "",
) -> dict[str, Any]:
    """Create a new alert dict with auto-generated id and timestamp."""
    return {
        "id": str(uuid.uuid4()),
        "severity": severity.lower(),
        "title": title,
        "affected_package": affected_package,
        "installed_version": installed_version,
        "patch_available": patch_available,
        "recommended_action": recommended_action,
        "alternative_action": alternative_action,
        "source": source,
        "cve_id": cve_id,
        "timestamp": datetime.now(timezone.utc).isoformat(),
        "status": "active",
        "resolved_at": None,
    }


def load_alerts(active_only: bool = True) -> list[dict[str, Any]]:
    """Load alerts from JSONL. If active_only, return only status='active'."""
    ensure_dirs()
    p = _path()
    if not p.exists():
        return []
    alerts: list[dict[str, Any]] = []
    try:
        for line in p.read_text().splitlines():
            line = line.strip()
            if not line:
                continue
            try:
                rec = json.loads(line)
                if active_only and rec.get("status") != "active":
                    continue
                alerts.append(rec)
            except json.JSONDecodeError:
                continue
    except OSError:
        return []
    # Sort by severity (critical > high > medium), then by timestamp
    sev_order = {"critical": 0, "high": 1, "medium": 2}
    alerts.sort(key=lambda a: (sev_order.get(a.get("severity", "medium"), 3), a.get("timestamp", "")))
    return alerts


def add_alert(alert: dict[str, Any]) -> bool:
    """Append a single alert to the JSONL file. Returns True on success."""
    ensure_dirs()
    p = _path()
    try:
        with open(p, "a") as f:
            f.write(json.dumps(alert) + "\n")
        return True
    except OSError:
        return False


def add_alerts(alerts: list[dict[str, Any]]) -> int:
    """Append multiple alerts. Returns count successfully written."""
    ensure_dirs()
    p = _path()
    count = 0
    try:
        with open(p, "a") as f:
            for alert in alerts:
                f.write(json.dumps(alert) + "\n")
                count += 1
    except OSError:
        pass
    return count


def dismiss_alert(alert_id: str) -> bool:
    """Mark an alert as dismissed (user chose to ignore it)."""
    return _update_status(alert_id, "dismissed")


def resolve_alert(alert_id: str) -> bool:
    """Mark an alert as resolved (issue fixed or no longer relevant)."""
    return _update_status(alert_id, "resolved")


def _update_status(alert_id: str, status: str) -> bool:
    """Update the status of an alert by id. Rewrites the entire file."""
    p = _path()
    if not p.exists():
        return False
    found = False
    lines: list[str] = []
    try:
        for line in p.read_text().splitlines():
            line = line.strip()
            if not line:
                continue
            try:
                rec = json.loads(line)
                if rec.get("id") == alert_id:
                    rec["status"] = status
                    rec["resolved_at"] = datetime.now(timezone.utc).isoformat()
                    found = True
                lines.append(json.dumps(rec))
            except json.JSONDecodeError:
                continue
        if found:
            p.write_text("\n".join(lines) + "\n")
        return found
    except OSError:
        return False


def clear_resolved(older_than_days: int = 7) -> int:
    """Remove resolved/dismissed alerts older than N days. Returns count removed."""
    p = _path()
    if not p.exists():
        return 0
    cutoff = datetime.now(timezone.utc).timestamp() - (older_than_days * 86400)
    kept: list[str] = []
    removed = 0
    try:
        for line in p.read_text().splitlines():
            line = line.strip()
            if not line:
                continue
            try:
                rec = json.loads(line)
                if rec.get("status") in ("resolved", "dismissed"):
                    ts = rec.get("resolved_at") or rec.get("timestamp", "")
                    try:
                        ts_epoch = datetime.fromisoformat(ts.replace("Z", "+00:00")).timestamp()
                        if ts_epoch < cutoff:
                            removed += 1
                            continue
                    except (ValueError, AttributeError):
                        pass
                kept.append(json.dumps(rec))
            except json.JSONDecodeError:
                continue
        p.write_text("\n".join(kept) + ("\n" if kept else ""))
    except OSError:
        return 0
    return removed


def get_alert_by_id(alert_id: str) -> dict[str, Any] | None:
    """Find a single alert by id. Returns None if not found."""
    for alert in load_alerts(active_only=False):
        if alert.get("id") == alert_id:
            return alert
    return None